def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_d = opp.count('D')

    if n >= 99:
        return 'D'

    if opp_d == 0:
        return 'C'

    first_DD = -1
    for i in range(n):
        if my[i] == 'D' and opp[i] == 'D':
            first_DD = i
            break

    last_test = -1
    if first_DD != -1:
        for i in range(first_DD + 1, n):
            if my[i] == 'C' and opp[i] == 'D':
                last_test = i

    my_c_streak = 0
    for x in reversed(my):
        if x == 'C':
            my_c_streak += 1
        else:
            break
    opp_d_streak = 0
    for x in reversed(opp):
        if x == 'D':
            opp_d_streak += 1
        else:
            break

    if my_c_streak > 0 and opp_d_streak > 0:
        if my_c_streak < 2:
            return 'C'
        else:
            return 'D'

    if n >= 3:
        last3_my = my[-3:]
        last3_opp = opp[-3:]
        if last3_my == ['D','D','D'] and last3_opp == ['D','D','D']:
            if last_test == -1 or (n - 1 - last_test) > 20:
                return 'C'

    last_my = my[-1]
    last_opp = opp[-1]

    if last_opp == 'D':
        if last_my == 'D':
            return 'D'
        else:
            recent_d = opp[-5:].count('D')
            if recent_d == 1 and rng.random() < 0.3:
                return 'C'
            return 'D'
    else:
        if last_my == 'D':
            return 'C'
        else:
            return 'C'
